mapper.delete:
DELETE ct
FROM content_tags ct
INNER JOIN contents c
ON c.id = ct.content_id
WHERE c.deleted_at IS NULL
AND (

    (
    c.type = #{content.type}
    AND c.external_source = #{content.externalSource}
    AND c.external_id = #{content.externalId}
    )

)

